const wewnetrzneId = Symbol("id");
const produkt = {
  name: "Rower",
  [wewnetrzneId]: 555
};

console.log(produkt[wewnetrzneId]); // 555

const wewnetrzneId = Symbol("id");
const produkt = { name: "Rower", [wewnetrzneId]: 555 };

console.log(Object.keys(produkt)); // ['name']
// klucz-symbol NIE jest widoczny w wyniku Object.keys() -
// widac wylacznie zwykly, tekstowy klucz 'name'

const kluczA = Symbol("id");
const kluczB = Symbol("id");
const dane = { [kluczA]: "wartosc" };

console.log(dane[kluczB]); // undefined
// kluczB to CALKOWICIE inny symbol niz kluczA, mimo tego samego opisu "id" -
// obiekt 'dane' nie ma zadnej wlasciwosci pod kluczem kluczB

function stworzUnikalnyId(nazwa) {
  return Symbol(nazwa);
}

const id1 = stworzUnikalnyId("uzytkownik");
const id2 = stworzUnikalnyId("uzytkownik");

console.log(id1 === id2); // false

const WERSJA = Symbol("wersja");
const konfiguracja = {
  jezyk: "pl",
  motyw: "ciemny",
  [WERSJA]: "1.0"
};

console.log(JSON.stringify(konfiguracja));
// '{"jezyk":"pl","motyw":"ciemny"}'
// klucz-symbol WERSJA CALKOWICIE znika z wyniku JSON.stringify(),
// mimo ze wlasciwosc realnie istnieje w obiekcie
